-- FRANCIS CREATOR STUDIO - 004 Auth Providers, Issuer RLS, and 100+100 Templates

-- 1. Support Phone-only & OAuth accounts cleanly in fcs_profiles
ALTER TABLE public.fcs_profiles ALTER COLUMN email DROP NOT NULL;
ALTER TABLE public.fcs_profiles ADD COLUMN IF NOT EXISTS auth_provider text;

CREATE INDEX IF NOT EXISTS idx_fcs_profiles_phone
  ON public.fcs_profiles(phone)
  WHERE phone IS NOT NULL AND length(trim(phone)) > 0;

CREATE OR REPLACE FUNCTION public.fcs_ensure_profile()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_email text;
  v_phone text;
  v_name text;
  v_avatar text;
  v_provider text;
  v_profile public.fcs_profiles%ROWTYPE;
  v_roles text[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT
    NULLIF(trim(u.email), ''),
    NULLIF(trim(u.phone), ''),
    COALESCE(
      NULLIF(trim(u.raw_user_meta_data->>'full_name'), ''),
      NULLIF(trim(u.raw_user_meta_data->>'name'), ''),
      NULLIF(split_part(coalesce(u.email, ''), '@', 1), ''),
      NULLIF(trim(u.phone), ''),
      'Creator'
    ),
    COALESCE(
      NULLIF(trim(u.raw_user_meta_data->>'avatar_url'), ''),
      NULLIF(trim(u.raw_user_meta_data->>'picture'), '')
    ),
    NULLIF(trim(u.raw_app_meta_data->>'provider'), '')
  INTO v_email, v_phone, v_name, v_avatar, v_provider
  FROM auth.users u
  WHERE u.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Auth user not found';
  END IF;

  VALUES (v_uid, CASE WHEN v_email IS NOT NULL THEN lower(v_email) ELSE NULL END, v_phone, v_name, v_avatar, COALESCE(v_provider, 'email'), now())
  ON CONFLICT (id) DO UPDATE
    SET last_active_at = now(),
        email = COALESCE(CASE WHEN EXCLUDED.email IS NOT NULL THEN lower(EXCLUDED.email) ELSE NULL END, public.fcs_profiles.email),
        phone = COALESCE(EXCLUDED.phone, public.fcs_profiles.phone),
        full_name = COALESCE(NULLIF(trim(public.fcs_profiles.full_name), ''), EXCLUDED.full_name),
        avatar_url = COALESCE(public.fcs_profiles.avatar_url, EXCLUDED.avatar_url),
        auth_provider = COALESCE(EXCLUDED.auth_provider, public.fcs_profiles.auth_provider);

  VALUES (v_uid, 'customer')
  ON CONFLICT (user_id, role) DO NOTHING;

  SELECT * INTO v_profile FROM public.fcs_profiles WHERE id = v_uid;
  SELECT COALESCE(array_agg(role), ARRAY['customer']) INTO v_roles FROM public.fcs_user_roles WHERE user_id = v_uid;

  RETURN jsonb_build_object(
    'profile', to_jsonb(v_profile),
    'roles', to_jsonb(v_roles)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fcs_ensure_profile() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fcs_ensure_profile() TO authenticated;

CREATE OR REPLACE FUNCTION public.fcs_guard_profile_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.fcs_has_any_role(auth.uid(), ARRAY['super_admin', 'admin'])
     AND current_setting('role', true) <> 'service_role' THEN
    NEW.status := OLD.status;
    NEW.suspended_reason := OLD.suspended_reason;
    NEW.suspended_at := OLD.suspended_at;
    IF OLD.email IS NOT NULL THEN
      NEW.email := OLD.email;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- 2. Fix fcs_authorized_issuers RLS so authenticated users can apply/update their organizations
DROP POLICY IF EXISTS fcs_issuers_auth_insert ON public.fcs_authorized_issuers;
CREATE POLICY fcs_issuers_auth_insert ON public.fcs_authorized_issuers
  FOR INSERT TO authenticated
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS fcs_issuers_own_update ON public.fcs_authorized_issuers;
CREATE POLICY fcs_issuers_own_update ON public.fcs_authorized_issuers
  FOR UPDATE TO authenticated
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

-- 3. Upsert all 100 Resume Templates
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  is_ats_friendly = EXCLUDED.is_ats_friendly,
  layout_config = EXCLUDED.layout_config,
  sort_order = EXCLUDED.sort_order;

